        unsafe { core::ptr::copy(src, dst, len1) };
        storage_ix_local = (storage_ix_local as c_ulong)
            .wrapping_add((len1 << 3 as c_int) as c_ulong)
            as size_t as size_t;
        *storage_ix = storage_ix_local;
        len = (len as c_ulong).wrapping_sub(len1 as c_ulong) as size_t as size_t;
        masked_pos = 0 as size_t;
    }

    let dst = storage.offset((storage_ix_local >> 3 as c_int) as isize);
    let src = input.offset(masked_pos as isize);
    // SAFETY: caller guarantees `storage` and `input` are valid for these byte ranges; overlap is not ruled out here, so use overlap-tolerant copy semantics.
    unsafe { core::ptr::copy(src, dst, len) };
    storage_ix_local = (storage_ix_local as c_ulong)
        .wrapping_add((len << 3 as c_int) as c_ulong)
        as size_t as size_t;
    *storage_ix = storage_ix_local;

    BrotliWriteBitsPrepareStorage(storage_ix_local, storage);
    if is_final_block != 0 {
        BrotliWriteBits(1 as size_t, 1 as uint64_t, storage_ix, storage);
        BrotliWriteBits(1 as size_t, 1 as uint64_t, storage_ix, storage);
        JumpToByteBoundary(storage_ix, storage);
    }
